const CHALLENGE_FORMS=3;const trainingVerify=$('#verify').onclick,trainingNext=$('#next').onclick,freeMode=$('#mode').onclick;function cloneBoard(){return new Map([...blocks].map(([k,b])=>[k,{...b}]))}function challengeUI(){const selected=!!run;$('#training').classList.toggle('active',!selected);$('#challenge').classList.toggle('active',selected);$('#challenge-info').hidden=!selected;$('#level-picker').hidden=selected;$('#mode').disabled=selected;$('#clue').hidden=selected;$('#clue-text').hidden=true;$('#start-challenge').hidden=!!run?.active;$('#finish-challenge').hidden=!run?.active;$('#challenge-nav').hidden=!run?.active;$('#verify').textContent=selected?'Enregistrer et passer à la forme suivante':'Valider ma forme';if(selected){$('#level-label').textContent=run.active?`ÉPREUVE · FORME ${run.slot+1} / ${CHALLENGE_FORMS}`:'ÉPREUVE';$('#stars').hidden=true;$('#next').hidden=true;$('#verify').hidden=!run.active;$('#match-label').textContent=run.active?'Ton score sera révélé à la fin.':'Trois formes à reproduire. Commence quand tu es prêt.';}else{$('#stars').hidden=true;$('#next').onclick=trainingNext;feedback()}}
function leaveChallenge(){if(run?.active&&!confirm('Quitter l’épreuve en cours ? Son score ne sera pas conservé.'))return false;run=null;document.body.classList.remove('challenge-finished');$('#results').close();challengeUI();return true}$('#training').onclick=()=>{if(leaveChallenge()){game=true;loadLevel(0);challengeUI()}};$('#challenge').onclick=()=>{if(run?.active)return;if(!game){game=true;$('.game-panel').hidden=false;document.body.classList.add('game');$('#mode').textContent='Dessin libre'}run={active:false,slot:0};window.location.hash='';galleryRoute();loadLevel(20);challengeUI()};
function startChallenge(){const candidates=Array.from({length:15},(_,i)=>i+10);for(let i=candidates.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[candidates[i],candidates[j]]=[candidates[j],candidates[i]]}run={active:true,ended:false,indices:candidates.slice(0,CHALLENGE_FORMS),scores:Array(CHALLENGE_FORMS).fill(0),boards:Array.from({length:CHALLENGE_FORMS},()=>new Map()),slot:0};game=true;document.body.classList.remove('challenge-finished');$('#results').close();$('#challenge-nav').replaceChildren();run.indices.forEach((_,i)=>{const b=document.createElement('button');b.textContent=i+1;b.dataset.slot=i;b.setAttribute('aria-label','Épreuve : forme '+(i+1));b.onclick=()=>switchChallenge(i);$('#challenge-nav').append(b)});loadLevel(run.indices[0]);challengeUI();markSlot();}function markSlot(){document.querySelectorAll('[data-slot]').forEach(b=>b.classList.toggle('active',Number(b.dataset.slot)===run.slot))}
function expired(){return !!run?.ended}function switchChallenge(slot){if(!run?.active||expired()||!Number.isInteger(slot)||slot<0||slot>=run.indices.length)return;run.boards[run.slot]=cloneBoard();run.slot=slot;loadLevel(run.indices[slot]);blocks=new Map([...run.boards[slot]].map(([k,b])=>[k,{...b}]));draw();challengeUI();markSlot()}
function finishChallenge(){if(!run?.active)return;run.scores[run.slot]=Math.max(run.scores[run.slot],comparison().percent);run.active=false;run.ended=true;run.result=Math.round(run.scores.reduce((a,b)=>a+b,0)/run.scores.length);document.body.classList.add('challenge-finished');$('#final-score').textContent=run.result+' / 100';$('#score-breakdown').replaceChildren();run.indices.forEach((index,i)=>{const p=document.createElement('p'),name=document.createElement('span'),score=document.createElement('strong');name.textContent=(i+1)+'. '+levels[index].title;score.textContent=run.scores[i]+' %';p.append(name,score);$('#score-breakdown').append(p)});$('#verify').hidden=true;$('#finish-challenge').hidden=true;$('#challenge-nav').hidden=true;$('#results').showModal()}
$('#start-challenge').onclick=startChallenge;$('#finish-challenge').onclick=finishChallenge;$('#verify').onclick=()=>{if(run?.active){if(!expired())switchChallenge((run.slot+1)%run.indices.length)}else if(!run)trainingVerify()};$('#mode').onclick=()=>{if(!run)freeMode()};$('#back-levels').onclick=()=>{leaveChallenge();loadLevel(0);challengeUI()};$('#retry-challenge').onclick=startChallenge;$('#results').addEventListener('cancel',e=>e.preventDefault());
const regularApply=apply;apply=function(f){if(run&&(!run.active||expired()))return;regularApply(f)};const regularUndo=undo,regularRedo=redo;undo=function(){if(run&&(!run.active||expired()))return;regularUndo()};redo=function(){if(run&&(!run.active||expired()))return;regularRedo()};$('#undo').onclick=()=>undo();$('#redo').onclick=()=>redo();const regularClear=$('#clear').onclick;$('#clear').onclick=()=>{if(run&&(!run.active||expired()))return;regularClear()};
